<template><div class="picker"><span>{{ label }}</span><div><q-btn outline no-caps icon="image" :label="path?'Replace image':'Choose image'" :loading="loading" @click="input.click()"/><q-btn v-if="path" flat round icon="close" color="negative" @click="$emit('removed')"/><small v-if="path">Image added</small><input ref="input" type="file" accept="image/*" hidden @change="upload"/></div></div></template>
<script setup>import { ref } from 'vue'; import { useQuasar } from 'quasar'; import { useQuizStore } from 'src/stores/quiz-store'; defineProps({label:String,path:String,compact:Boolean}); const emit=defineEmits(['uploaded','removed']),quiz=useQuizStore(),$q=useQuasar(),input=ref(),loading=ref(false); const upload=async e=>{const f=e.target.files?.[0];if(!f)return;loading.value=true;try{emit('uploaded',await quiz.uploadImage(f))}catch(err){$q.notify({type:'negative',message:err.response?.data?.message||'Image upload failed'})}finally{loading.value=false;e.target.value=''}}</script>
<style scoped>.picker{padding:12px;border:1px dashed #cbd9ec;border-radius:11px;background:#f8fbff}.picker>span{display:block;margin-bottom:8px;color:#5b6f8e;font-size:.75rem;font-weight:700}.picker>div{display:flex;align-items:center;gap:5px}.picker small{color:#2b9b70}</style>
